@contextmanager
def exclusive_file_lock(path: Path) -> Iterator[None]:
    """Serialize the SQLite outbox -> JSONL handoff across Hub processes."""
    fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o640)
    try:
        os.chmod(path, 0o640)
        if os.name == "nt":
            import msvcrt

            if os.fstat(fd).st_size == 0:
                os.write(fd, b"\0")
                os.fsync(fd)
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_LOCK, 1)
        else:
            import fcntl

            fcntl.flock(fd, fcntl.LOCK_EX)
        try:
            yield
        finally:
            if os.name == "nt":
                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
            else:
                fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)


class QueueDB:
    def __init__(self, root: str | os.PathLike[str]):
        self.root = Path(root)
        self.db_path = self.root / "jobs.sqlite"
        self.events_path = self.root / "job_events.jsonl"
        self.health_path = self.root / "health.json"
        self.schema_path = Path(__file__).with_name("schema.sql")

    def initialize(self) -> None:
        self.root.mkdir(parents=True, exist_ok=True)
        os.chmod(self.root, 0o750)
        for name in ("backups", "incoming", "artifacts", "logs"):
            directory = self.root / name
            directory.mkdir(exist_ok=True)
            os.chmod(directory, 0o750)
        with closing(self.connect()) as con:
            has_meta = con.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='schema_meta'"
            ).fetchone()
            if has_meta:
                existing = con.execute(
                    "SELECT value FROM schema_meta WHERE key='schema_version'"
                ).fetchone()
                if existing is None or int(existing[0]) not in {1, SCHEMA_VERSION}:
                    raise FailClosed(f"unsupported pre-migration queue schema: {existing!r}")
            con.executescript(self.schema_path.read_text(encoding="utf-8"))
            row = con.execute(
                "SELECT value FROM schema_meta WHERE key='schema_version'"
            ).fetchone()
            if row is None or int(row[0]) != SCHEMA_VERSION:
                raise FailClosed(f"unsupported queue schema: {row!r}")
            foreign_key_errors = con.execute("PRAGMA foreign_key_check").fetchall()
            if foreign_key_errors:
                raise FailClosed(f"queue foreign_key_check failed with {len(foreign_key_errors)} row(s)")
        for path in (self.db_path, self.events_path, self.root / ".job_events.lock"):
            if path.exists():
                os.chmod(path, 0o640)
        fsync_directory(self.root)

    def connect(self) -> sqlite3.Connection:
        con = sqlite3.connect(self.db_path, timeout=30, isolation_level=None)
        try:
            con.row_factory = sqlite3.Row
            con.execute("PRAGMA foreign_keys=ON")
            con.execute("PRAGMA busy_timeout=30000")
            mode = con.execute("PRAGMA journal_mode=WAL").fetchone()[0]
            if str(mode).lower() != "wal":
                raise FailClosed(f"WAL mode unavailable: {mode}")
            con.execute("PRAGMA synchronous=FULL")
            os.chmod(self.db_path, 0o640)
            for suffix in ("-wal", "-shm"):
                sidecar = Path(f"{self.db_path}{suffix}")
                if sidecar.exists():
                    os.chmod(sidecar, 0o640)
            return con
        except BaseException:
            con.close()
            raise

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        con = self.connect()
        try:
            con.execute("BEGIN IMMEDIATE")
            yield con
            con.execute("COMMIT")
        except BaseException:
            if con.in_transaction:
                con.execute("ROLLBACK")
            raise
        finally:
            con.close()

    @staticmethod
    def _event(con: sqlite3.Connection, event_type: str, entity_id: str, payload: Any) -> None:
        con.execute(
            "INSERT INTO event_outbox(event_type,entity_id,occurred_at,payload_json) VALUES(?,?,?,?)",
            (event_type, entity_id, utc_now(), canonical_json(payload)),
        )

